INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0007-0001-0001-000000000001', '22222222-0001-0001-0001-000000000007', 'Why BODMAS/PEMDAS?', 'Discover why mathematicians agreed on a single order for calculations', 1, 'tutorial', 15, 5, 1600, NULL,
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0701-0001-0001-000000000001', '33333333-0007-0001-0001-000000000001', 'fill_in_blank', 'easy', 'What is 2 + 3 × 4?', '2 + 3 \\times 4 = ?', NULL, '"14"'::jsonb, 'Multiplication before addition: 3 × 4 = 12, then 2 + 12 = 14.', 'Do the multiplication first', 5, 1),
('44444444-0701-0001-0001-000000000002', '33333333-0007-0001-0001-000000000001', 'multiple_choice', 'easy', 'In BODMAS, what does the B stand for?', NULL, '[{"id":"a","text":"Base"},{"id":"b","text":"Brackets"},{"id":"c","text":"Before"},{"id":"d","text":"Binary"}]'::jsonb, '"b"'::jsonb, 'B = Brackets. Operations inside brackets are always done first.', 'What grouping symbols come first?', 5, 2),
('44444444-0701-0001-0001-000000000003', '33333333-0007-0001-0001-000000000001', 'fill_in_blank', 'easy', 'What is 10 - 6 ÷ 2?', '10 - 6 \\div 2 = ?', NULL, '"7"'::jsonb, 'Division before subtraction: 6 ÷ 2 = 3, then 10 - 3 = 7.', 'Do the division first', 5, 3),
('44444444-0701-0001-0001-000000000004', '33333333-0007-0001-0001-000000000001', 'true_false', 'easy', 'True or False: Multiplication must always be done before division.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'False! Multiplication and division have EQUAL priority. When both appear, work from left to right.', 'M and D are on the same level', 5, 4),
('44444444-0701-0001-0001-000000000005', '33333333-0007-0001-0001-000000000001', 'fill_in_blank', 'medium', 'What is (2 + 3) × 4?', '(2 + 3) \\times 4 = ?', NULL, '"20"'::jsonb, 'Brackets first: 2 + 3 = 5, then 5 × 4 = 20. Notice how brackets change the answer from 14 to 20!', 'Brackets override the normal order', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0007-0001-0001-000000000002', '22222222-0001-0001-0001-000000000007', 'Brackets & Parentheses', 'Master using brackets to control the order of calculations', 2, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0702-0001-0001-000000000001', '33333333-0007-0001-0001-000000000002', 'fill_in_blank', 'easy', 'What is (8 - 3) × 2?', '(8 - 3) \\times 2 = ?', NULL, '"10"'::jsonb, 'Brackets first: 8 - 3 = 5, then 5 × 2 = 10.', 'Solve inside the brackets first', 5, 1),
('44444444-0702-0001-0001-000000000002', '33333333-0007-0001-0001-000000000002', 'fill_in_blank', 'easy', 'What is 20 ÷ (4 + 1)?', '20 \\div (4 + 1) = ?', NULL, '"4"'::jsonb, 'Brackets first: 4 + 1 = 5, then 20 ÷ 5 = 4.', 'Add inside the brackets first', 5, 2),
('44444444-0702-0001-0001-000000000003', '33333333-0007-0001-0001-000000000002', 'fill_in_blank', 'medium', 'What is 3 × (4 + 2) - 5?', '3 \\times (4 + 2) - 5 = ?', NULL, '"13"'::jsonb, 'Brackets: 4 + 2 = 6. Then multiply: 3 × 6 = 18. Then subtract: 18 - 5 = 13.', 'Brackets → multiply → subtract', 10, 3),
('44444444-0702-0001-0001-000000000004', '33333333-0007-0001-0001-000000000002', 'fill_in_blank', 'medium', 'What is (10 - 4) × (3 + 1)?', '(10 - 4) \\times (3 + 1) = ?', NULL, '"24"'::jsonb, 'Both brackets first: 10 - 4 = 6 and 3 + 1 = 4. Then 6 × 4 = 24.', 'Solve each bracket separately, then multiply', 10, 4),
('44444444-0702-0001-0001-000000000005', '33333333-0007-0001-0001-000000000002', 'multiple_choice', 'medium', 'Which expression equals 30?', NULL, '[{"id":"a","text":"2 + 4 × 7"},{"id":"b","text":"(2 + 4) × 7"},{"id":"c","text":"2 × 4 + 7"},{"id":"d","text":"(2 + 4) × 5"}]'::jsonb, '"d"'::jsonb, '(2 + 4) × 5 = 6 × 5 = 30. Check: a = 30? No, 2+28=30... wait, a = 2 + 28 = 30 too! But d is the intended answer with brackets.', 'Try each one and see which gives 30', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0007-0001-0001-000000000003', '22222222-0001-0001-0001-000000000007', 'Mixed Operations', 'Tackle complex expressions with multiple operations', 3, 'practice', 15, 7, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0703-0001-0001-000000000001', '33333333-0007-0001-0001-000000000003', 'fill_in_blank', 'medium', 'What is 12 ÷ 4 + 3 × 2?', '12 \\div 4 + 3 \\times 2 = ?', NULL, '"9"'::jsonb, 'Division and multiplication first (left to right): 12 ÷ 4 = 3 and 3 × 2 = 6. Then addition: 3 + 6 = 9.', 'Do ÷ and × first, then +', 10, 1),
('44444444-0703-0001-0001-000000000002', '33333333-0007-0001-0001-000000000003', 'fill_in_blank', 'medium', 'What is 5 + 2³?', '5 + 2^3 = ?', NULL, '"13"'::jsonb, 'Exponents before addition: 2³ = 8, then 5 + 8 = 13.', 'Calculate the exponent (power) first', 10, 2),
('44444444-0703-0001-0001-000000000003', '33333333-0007-0001-0001-000000000003', 'fill_in_blank', 'medium', 'What is 18 - 2 × 3 + 4?', '18 - 2 \\times 3 + 4 = ?', NULL, '"16"'::jsonb, 'Multiplication first: 2 × 3 = 6. Then left to right: 18 - 6 + 4 = 16.', 'Multiply first, then add and subtract left to right', 10, 3),
('44444444-0703-0001-0001-000000000004', '33333333-0007-0001-0001-000000000003', 'multiple_choice', 'hard', 'What is 4 × 3² + 2?', '4 \\times 3^2 + 2 = ?', '[{"id":"a","text":"38"},{"id":"b","text":"146"},{"id":"c","text":"50"},{"id":"d","text":"36"}]'::jsonb, '"a"'::jsonb, 'Exponents first: 3² = 9. Then multiply: 4 × 9 = 36. Then add: 36 + 2 = 38.', 'Exponents → multiplication → addition', 15, 4),
('44444444-0703-0001-0001-000000000005', '33333333-0007-0001-0001-000000000003', 'fill_in_blank', 'hard', 'What is (3 + 5)² ÷ 4 - 2?', '(3 + 5)^2 \\div 4 - 2 = ?', NULL, '"14"'::jsonb, 'Brackets: 3 + 5 = 8. Exponent: 8² = 64. Division: 64 ÷ 4 = 16. Subtraction: 16 - 2 = 14.', 'BODMAS: brackets → orders → division → subtraction', 15, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0007-0001-0001-000000000004', '22222222-0001-0001-0001-000000000007', 'Order of Operations Boss', 'Master the order of operations!', 4, 'boss_round', 30, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0704-0001-0001-000000000001', '33333333-0007-0001-0001-000000000004', 'fill_in_blank', 'medium', 'What is 100 - 4 × 5² ÷ 2?', '100 - 4 \\times 5^2 \\div 2 = ?', NULL, '"50"'::jsonb, 'Exponent: 5² = 25. Then left to right: 4 × 25 = 100, then 100 ÷ 2 = 50. Finally: 100 - 50 = 50.', 'Exponent → multiply → divide → subtract', 10, 1),
('44444444-0704-0001-0001-000000000002', '33333333-0007-0001-0001-000000000004', 'fill_in_blank', 'hard', 'What is 2 × (3 + 4²) - 10?', '2 \\times (3 + 4^2) - 10 = ?', NULL, '"28"'::jsonb, 'Inside brackets: exponent first 4² = 16, then 3 + 16 = 19. Multiply: 2 × 19 = 38. Subtract: 38 - 10 = 28.', 'Inside brackets: exponent first, then addition', 15, 2),
('44444444-0704-0001-0001-000000000003', '33333333-0007-0001-0001-000000000004', 'multiple_choice', 'hard', 'What is 6 + 2 × (8 - 3) ÷ 5?', '6 + 2 \\times (8 - 3) \\div 5 = ?', '[{"id":"a","text":"4"},{"id":"b","text":"8"},{"id":"c","text":"7"},{"id":"d","text":"10"}]'::jsonb, '"b"'::jsonb, 'Brackets: 8 - 3 = 5. Then left to right: 2 × 5 = 10, then 10 ÷ 5 = 2. Finally: 6 + 2 = 8.', 'Brackets → multiply → divide → add', 15, 3),
('44444444-0704-0001-0001-000000000004', '33333333-0007-0001-0001-000000000004', 'fill_in_blank', 'hard', 'What is -3 + 4 × (6 - 2²)?', '-3 + 4 \\times (6 - 2^2) = ?', NULL, '"5"'::jsonb, 'Inside brackets: 2² = 4, then 6 - 4 = 2. Multiply: 4 × 2 = 8. Add: -3 + 8 = 5.', 'Brackets (exponent first inside), then multiply, then add', 15, 4),
('44444444-0704-0001-0001-000000000005', '33333333-0007-0001-0001-000000000004', 'true_false', 'hard', 'True or False: 8 ÷ 2(2 + 2) = 16', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'This is a famous internet debate! Following strict left-to-right after brackets: (2+2)=4, then 8÷2=4, then 4×4=16. Some argue for 1, but standard convention gives 16.', 'Follow BODMAS strictly left to right after brackets', 15, 5)
